const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
// The webhook delivers the raw body so a malformed JSON returns 400 DATOS_INVALIDOS
// instead of n8n's own 422 parsing error.
let parsed = {};
const item = $input.first();
if (item.binary && item.binary.data) {
  const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
  try {
    parsed = JSON.parse(buf.toString('utf8'));
  } catch (e) {
    return [{ json: { decision: 'INVALIDO', request_id: null,
      errores: ['El cuerpo de la solicitud debe ser un JSON válido'], data: {} } }];
  }
}
const b = (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) ? parsed : {};
const str = (v) => (typeof v === 'string' ? v.trim() : null);
const up = (v) => (str(v) === null ? null : str(v).toUpperCase());
const errores = [];

const requestId = str(b.request_id);
const requestIdValido = requestId !== null && UUID_RE.test(requestId);
if (!requestIdValido) errores.push('request_id debe ser un UUID válido');

const distrito = up(b.distrito);
if (!['MIRAFLORES', 'SURQUILLO', 'OTRO'].includes(distrito)) {
  errores.push('distrito debe ser MIRAFLORES, SURQUILLO u OTRO');
}

const categoria = up(b.categoria);
const categoriaValida = ['ACUMULACION', 'OMISION_RECOJO', 'VOLUMINOSO'].includes(categoria);
if (!categoriaValida) errores.push('categoria debe ser ACUMULACION, OMISION_RECOJO o VOLUMINOSO');

// Length is counted in characters (code points) like PostgreSQL does, not in UTF-16 units.
const chars = (s) => Array.from(s).length;
const wellFormed = (s) => { try { encodeURIComponent(s); return true; } catch (e) { return false; } };
const hasControl = (s, allowLineBreaks) =>
  (allowLineBreaks ? /[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/ : /[\u0000-\u001F\u007F]/).test(s);

const referencia = str(b.referencia);
if (referencia === null || chars(referencia) < 5 || chars(referencia) > 120) {
  errores.push('referencia debe tener entre 5 y 120 caracteres');
} else if (!wellFormed(referencia) || hasControl(referencia, false)) {
  errores.push('referencia no puede contener saltos de línea ni caracteres de control');
}
const descripcion = str(b.descripcion);
if (descripcion === null || chars(descripcion) < 15 || chars(descripcion) > 200) {
  errores.push('descripcion debe tener entre 15 y 200 caracteres');
} else if (!wellFormed(descripcion) || hasControl(descripcion, true)) {
  errores.push('descripcion contiene caracteres que no se pueden guardar');
}
if (typeof b.obstruccion !== 'boolean') errores.push('obstruccion debe ser verdadero o falso');

const sector = up(b.sector);
if (distrito === 'MIRAFLORES' && !sector) errores.push('sector es obligatorio para MIRAFLORES');

if (categoria === 'ACUMULACION') {
  if (!Number.isInteger(b.bolsas) || b.bolsas < 1 || b.bolsas > 50) {
    errores.push('bolsas debe ser un entero entre 1 y 50 para ACUMULACION');
  }
} else if (categoriaValida && b.bolsas !== undefined && b.bolsas !== null) {
  errores.push('bolsas solo aplica a ACUMULACION');
}

let decision = 'ADMITIDO';
if (errores.length > 0) decision = 'INVALIDO';
else if (distrito !== 'MIRAFLORES') decision = 'FUERA_JURISDICCION';

return [{ json: {
  decision,
  request_id: requestIdValido ? requestId.toLowerCase() : null,
  errores,
  data: {
    sector,
    categoria,
    referencia,
    descripcion,
    obstruccion: b.obstruccion,
    bolsas: categoria === 'ACUMULACION' ? b.bolsas : null,
  },
} }];

const j = $input.first().json;
return [{ json: {
  http_status: 400,
  resultado: 'DATOS_INVALIDOS',
  request_id: j.request_id,
  body: { codigo: 'DATOS_INVALIDOS', mensaje: 'Los datos enviados no son válidos. Revise los campos indicados.', detalle: j.errores },
} }];

const j = $input.first().json;
return [{ json: {
  http_status: 422,
  resultado: 'FUERA_DE_JURISDICCION',
  request_id: j.request_id,
  body: { codigo: 'FUERA_DE_JURISDICCION', mensaje: 'El reporte corresponde a otro distrito. Esta simulación solo atiende reportes de Miraflores.' },
} }];

const j = $input.first().json;
const rid = $('Validar y normalizar').first().json.request_id;
return [{ json: {
  http_status: j.http_status,
  resultado: j.resultado,
  request_id: rid,
  reporte_id: j.reporte_id,
  body: {
    codigo_publico: j.codigo_publico,
    estado: j.estado,
    prioridad: j.prioridad,
    cola: j.cola,
    plazo_horas: j.plazo_horas,
    fecha_limite: j.fecha_limite_lima,
    fecha_limite_iso: j.fecha_limite_iso,
    duplicado: j.duplicado,
    mensaje: j.duplicado ? 'Este reporte ya estaba registrado. Se devuelve el original.' : 'Reporte registrado correctamente.',
  },
} }];

const rid = $('Validar y normalizar').first().json.request_id;
return [{ json: {
  http_status: 409,
  resultado: 'IDENTIFICADOR_EN_CONFLICTO',
  request_id: rid,
  body: { codigo: 'IDENTIFICADOR_EN_CONFLICTO', mensaje: 'Ya existe un reporte con ese identificador y datos distintos. No se modificó el reporte original.' },
} }];

const rid = $('Validar y normalizar').first().json.request_id;
return [{ json: {
  http_status: 422,
  resultado: 'SECTOR_NO_HABILITADO',
  request_id: rid,
  body: { codigo: 'SECTOR_NO_HABILITADO', mensaje: 'El sector indicado no existe o no está habilitado.' },
} }];

const rid = $('Validar y normalizar').first().json.request_id;
// The database rejected the VALUE (constraint, text encoding, size): that is a data problem the user can fix,
// not an availability problem. Connection, permission and timeout errors stay 503.
const detalle = JSON.stringify($input.first().json || {});
const errorDeDatos = /violates (check|not-null|foreign key) constraint|invalid byte sequence|invalid input syntax|value too long|out of range|cannot be converted/i.test(detalle)
  && !/permission denied|password|authentication|connect|timeout|ECONN|terminating|role /i.test(detalle);
if (errorDeDatos) {
  return [{ json: {
    http_status: 400,
    resultado: 'DATOS_INVALIDOS',
    request_id: rid,
    body: { codigo: 'DATOS_INVALIDOS', mensaje: 'Los datos enviados no son válidos. Revise los campos indicados.', detalle: ['Algún campo tiene un valor que no se puede guardar.'] },
  } }];
}
return [{ json: {
  http_status: 503,
  resultado: 'ERROR_PERSISTENCIA',
  request_id: rid,
  body: { codigo: 'ERROR_PERSISTENCIA', mensaje: 'No se pudo confirmar el registro. Puede reintentar el mismo envío.' },
} }];

const j = $input.first().json;
// Automated tests send "X-Origen: prueba" so they can be told apart from demo visitors.
const h = $('Webhook reportes').first().json.headers || {};
const origen = String(h['x-origen'] || '').toLowerCase() === 'prueba' ? 'prueba' : 'demo';
$execution.customData.set('http_status', String(j.http_status));
$execution.customData.set('resultado', j.resultado);
$execution.customData.set('origen', origen);
if (j.request_id) $execution.customData.set('request_id', j.request_id);
if (j.reporte_id) $execution.customData.set('reporte_id', String(j.reporte_id));
return [{ json: { ...j, origen } }];
